<?php
session_start();if(!isset($_SESSION["admin"])){header("Location:index.php");exit;}require"database.php";
if(isset($_GET["delete"])){$id=(int)$_GET["delete"];$conn->query("DELETE FROM subjects WHERE subject_id=$id");header("Location:subjects.php");exit;}
if($_SERVER["REQUEST_METHOD"]==="POST"){$s=$conn->prepare("INSERT INTO subjects(subject_code,subject_name,units,course,year_level) VALUES(?,?,?,?,?)");$s->bind_param("ssdss",$_POST["subject_code"],$_POST["subject_name"],$_POST["units"],$_POST["course"],$_POST["year_level"]);$s->execute();header("Location:subjects.php");exit;}
$list=$conn->query("SELECT * FROM subjects ORDER BY subject_code");
?>
